import React from 'react';
import './SquareButton.css'; // Import the CSS file for your button styles
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import PublicIcon from '@mui/icons-material/Public';
import InfoIcon from '@mui/icons-material/Info';
import SummarizeIcon from '@mui/icons-material/Summarize';
import TerminalIcon from '@mui/icons-material/Terminal';

function SquareButton({ selected, share, code, text, onClick, icon, textOnly }) {
  let style = "square-button";
  if (selected) {
    style = textOnly ? "text-button-selected" : "square-button-selected";
  } else if (share) {
    style = "square-button-share";
  } else if (textOnly) {
    style = "text-button";
  }

  return (
    <button className={style} onClick={onClick}>
      {code ? (
        <code>{text}</code>
      ) : (
        <div>
          {/* If the text is "Inicio", show a Home icon from Material UI */}

          {text === 'Inicio' && <PublicIcon /> }
          {text === 'Reportes' && <SummarizeIcon /> }
          {text === 'Modelos' && <TerminalIcon /> }
          {text === '?' && <InfoIcon /> }


          {text !== 'Reportes' && text !== 'Inicio' && text!== "Modelos" && text!== "?" && text }


          {/* If another icon prop is provided, render the FontAwesome icon */}
          {icon && <FontAwesomeIcon icon={icon} />}
        </div>
      )}
    </button>
  );
}

export default SquareButton;
