import React, { useState, useEffect } from 'react';
import './Bio.css';
import Header from './Header';
import "@fontsource/montserrat";
import { linearRegression, linearRegressionLine } from 'simple-statistics';
import ReportLecaps from './Lecaps';
import ReportHardDollar from './HardDollar';
import ReportBonosCER from './CER';
import { ReportFuturos, ReportSinteticosDL } from './Futuros';
import {
  DollarSign,
  BarChart3,
  TrendingUp,
  CalendarDays,
  LineChart,
  Banknote,
  ArrowRightLeft,
  Database,
  FlaskConical,
  BadgeDollarSign
} from 'lucide-react';

const BACK_URL = process.env.REACT_APP_BACK_URL;

function useIsMobile(breakpoint = 600) {
  const [isMobile, setIsMobile] = useState(
    typeof window !== 'undefined' && window.innerWidth < breakpoint
  );

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < breakpoint);
    };

    window.addEventListener('resize', handleResize);
    handleResize();

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, [breakpoint]);

  return isMobile;
}

function cleanReport(report){
  report.map(item => {item["price day %"]= (item["price day %"]*100).toFixed(2)});
  report.map(item => {item["price ytd %"]= (item["price ytd %"]*100).toFixed(2)});
  report.map(item => {item["YTM"]= (item["YTM"]).toFixed(3)});
  report.map(item => {item["MD"]= (item["MD"]).toFixed(3)});
  report.map(item => {item["Parity"]= (item["Parity"]).toFixed(2)});
}

const calculateTrendLine = (data) => {
  if (!data || data.length === 0) return [];
  const points = data.map(d => [d.dias, d.tem]);
  const regression = linearRegression(points);
  const lineFunction = linearRegressionLine(regression);

  const diasValues = data.map(d => d.dias);
  const minDias = Math.min(...diasValues);
  const maxDias = Math.max(...diasValues);

  return [
    { dias: minDias, tem: lineFunction(minDias) },
    { dias: maxDias, tem: lineFunction(maxDias) },
  ];
};

function Reports() {
  const [reportData, setReportData] = useState([]);
  const [trendDataS, setTrendDataS] = useState([]);
  const [reportDate, setReportDate] = useState("");
  const [bonosHD, setBonosHD] = useState({});
  const [bonosCER, setBonosCER] = useState({});
  const [futurosUSD, setFuturosUSD] = useState({});
  const [sinteticos, setSinteticos] = useState({});
  const [aiReports, setAiReports] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [dolar, setDolar] = useState({});
  const isMobile = useIsMobile(600);

  useEffect(() => {
    async function fetchAiReports() {
      try {
        const res = await fetch(`${BACK_URL}/ai`);
        if (!res.ok) throw new Error(`Server error: ${res.status}`);
        const data = await res.json();
        setAiReports(data);
      } catch (err) {
        console.error('Failed to load AI reports:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }

    fetchAiReports();
  }, []);

  useEffect(() => {
    const fetchDolar = async () => {
      try {
        const response = await fetch('https://dolarapi.com/v1/dolares/oficial');
        if (!response.ok) throw new Error('Network response was not ok');
        const data = await response.json();
        setDolar(data);
      } catch (error) {
        setError(error.message);
        console.error('Error al obtener el dólar:', error);
      }
    };

    fetchDolar();
  }, []);

  useEffect(() => {
    fetch(`${BACK_URL}/report`)
      .then(response => {
        if (!response.ok) throw new Error('Network response was not ok');
        return response.json();
      })
      .then(data => {
        setReportDate(data["date"]);
       
        let bonaresReport = data["bonares"]["report"];
        let globalesReport = data["globales"]["report"];
        cleanReport(bonaresReport);
        cleanReport(globalesReport);

        setBonosHD({
          bonares: bonaresReport,
          bonares_cf: data["bonares"]["cf"],
          globales: globalesReport,
          globales_cf : data["globales"]["cf"],
        });

        setBonosCER({
          cer: data["cer"]["report"],
          cer_cf : data["cer"]["cf"],
          be_inflation : data["cer"]["be_inflation"]
        });

        setFuturosUSD({
          futuros: data["futuros"]["report"]
        });

        setSinteticos({
          report: data["sinteticos"]["report"],
        });

        data = data["lecaps"];
        data.sort((a, b) => a["dias"] - b["dias"]);
        data.map(item => {item["breakeven"]= item["total"]*dolar["venta"]/item["precio"]});
        data.map(item => {item["sup"]= (1400 * (1 + 0.01)**(item["dias"] / 30))});
        data.map(item => {item["tem"]= item["tem"]*100});
        data.map(item => {item["price day %"]= (item["price day %"]*100).toFixed(2)});
        data.map(item => {item["price ytd %"]= (item["price ytd %"]*100).toFixed(2)});

        setTrendDataS(calculateTrendLine(data.filter(item => item['tem'] > 0)));
        setReportData(data);
        setError(null);
      })
      .catch(err => {
        setError(err.message);
        setReportData(null);
      })
      .finally(() => {
        setLoading(false);
      });
  }, [dolar.venta]);

  const iconStyle = { marginRight: 6, color: '#006400' }; // Dark green

  return (
    <div>
      <Header option={'Reports'} />
      <div className="reports-container">
        <h1 style={{
          textAlign: 'left',
          marginBottom: '5px',
          marginLeft: '10px',
          display: 'flex',
          alignItems: 'center',
          fontSize: '24px',
          fontWeight: 'bold',
          color: "white",
        }}>
          <CalendarDays size={28} style={{ ...iconStyle, marginRight: 10 }} />
          <span style={{ marginTop: 2 }}>Argentina {reportDate}</span>
        </h1>

        <h2 style={{ color: "white", fontSize: "16px", fontWeight: "bold", marginLeft:"10px", marginBottom: "20px", display: 'flex', alignItems: 'center' }}>
          <Banknote size={18} style={iconStyle} />
          Renta Fija
        </h2>

        <ReportLecaps aiReports={aiReports||{}} isMobile={isMobile} data={reportData||[]} dolar={dolar} trend={trendDataS} title={"Tasa Fija Pesos"} />
        <ReportHardDollar aiReports={aiReports||{}} isMobile={isMobile} data={bonosHD||{}} dolar={dolar} title={"Bonos Hard Dollar"} />
        <ReportBonosCER aiReports={aiReports||{}} isMobile={isMobile} data={bonosCER||{}} dolar={dolar} title={"Bonos CER"} />

        <h2 style={{ color: "white", fontSize: "16px", fontWeight: "bold", marginLeft:"10px", marginBottom: "20px", display: 'flex', alignItems: 'center' }}>
          <BadgeDollarSign size={18} style={iconStyle} />
          Futuros
        </h2>

        <ReportFuturos aiReports={aiReports||{}} isMobile={isMobile} data={futurosUSD||{}} dolar={dolar} title={"Futuros de USD"} />

        <h2 style={{ color: "white", fontSize: "16px", fontWeight: "bold", marginLeft:"10px", marginBottom: "20px", display: 'flex', alignItems: 'center' }}>
          <FlaskConical size={18} style={iconStyle} />
          Sintéticos
        </h2>

        <ReportSinteticosDL aiReports={aiReports||{}} isMobile={isMobile} data={sinteticos||[]} dolar={dolar} title={"Sintéticos Dollar-Linked"} />
      </div>
    </div>
  );
}

export default Reports;
