const AmortizationChart = ({ data, isMobile }) => {
    const chartData = data.map(row => ({
      date: row.date,
      Interest: row.I.toFixed(3),
      Amortization: row.A.toFixed(3),
    }));
  
    return (
      <ResponsiveContainer aspect={isMobile ? 1.5 : 2.5} width="100%" >
        <BarChart
          data={chartData}
          margin={{ top: 10, right: 10, left: 0, bottom: 5 }}
        >
          <XAxis 
            dataKey="date" 
            tick={{ fill: '#fff', fontSize: 12 }} 
            axisLine={{ stroke: '#555' }} 
            tickLine={{ stroke: '#555' }}
          />
          <YAxis 
            tick={{ fill: '#fff', fontSize: 12 }} 
            axisLine={{ stroke: '#555' }} 
            tickLine={{ stroke: '#555' }}
          />
          <Tooltip 
            contentStyle={{ backgroundColor: '#222', borderColor: '#555' }}
            itemStyle={{ color: '#fff' }}
            labelStyle={{ color: '#aaa' }}
          />
          <Legend 
            verticalAlign="top" 
            wrapperStyle={{ color: '#fff' }}
          />
  
          {/* Colores adaptados a fondo negro */}
          <Bar 
            dataKey="Interest" 
            stackId="a" 
            name="Cupón Interés" 
            fill="#16c784" 
          />
          <Bar 
            dataKey="Amortization" 
            stackId="a" 
            name="Pago de Amortización" 
            fill="#ea3943" 
          />
        </BarChart>
      </ResponsiveContainer>
    );
  };
  


