// The "container" component that holds the state and switches views
function BonosHDTable({pesos=false, data, cfs,isMobile }) {
    const [selected, setSelected] = useState(null);
  
    // If something's selected, show the detail pane
    if (selected) {
      return (
        <TickerDetail
          ticker={selected['ticker']}
          cfs={cfs}
          onBack={() => setSelected(null)}
          isMobile={isMobile}
        />
      );
    }
  
    // Otherwise show the table view
    return (
      <BonaresTableView
        data={data}
        pesos={pesos}
        onRowClick={item => setSelected(item)}
        isMobile={isMobile}
      />
    );
  }

const bonosCERChart = (data, isMobile) => {
    // Polynomial regression calculation
    const calculateTrend = (dataPoints, order = 2) => {
      if (!dataPoints || dataPoints.length < 2) return [];
      const points = dataPoints.map(p => [p.MD, p.YTM]);
      const result = regression.polynomial(points, { order, precision: 6 });
      const minX = Math.min(...dataPoints.map(p => p.MD));
      const maxX = Math.max(...dataPoints.map(p => p.MD));
      
      return Array.from({ length: 100 }, (_, i) => {
        const x = minX + (maxX - minX) * (i / 100);
        const y = result.predict(x)[1];
        return { MD: x, YTM: y };
      });
    };
  
    // Calculate trends for both bond types
    const cerTrend = calculateTrend(data["cer"] || []);
  
    return (
      <>
        <h2 style={{ textAlign: 'center', margin: '10px 0', fontSize: 'clamp(1.2rem, 4vw, 1.5rem)' }}>
          Curva CER 
        </h2>
        <div style={{ position: 'relative', width: '100%' }}>
          <ResponsiveContainer aspect={isMobile ? 1.5 : 2.5} width="100%" height="100%">
            <ComposedChart margin={{ top: 10, right: 10, left: 10, bottom: 60 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#444" />
              
              <XAxis
                type="number"
                dataKey="MD"
                name="MD"
                
                tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
                label={{
                  value: 'MD',
                  position: 'bottom',
                  offset: 10,
                  fill: '#fff',
                  style: { fontSize: 'clamp(10px, 3vw, 14px)' }
                }}
              />
              
              <YAxis
                type="number"
                dataKey="YTM"
                name="YTM"
                domain={[10, 13]}
                tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
                label={{
                  value: 'YTM (%)',
                  angle: -90,
                  position: 'left',
                  fill: '#fff',
                  style: { fontSize: 'clamp(10px, 3vw, 14px)' }
                }}
              />
              
              <Legend
                verticalAlign="top"
                wrapperStyle={{ paddingBottom: 20 }}
                payload={[
                  { value: 'Bono CER', type: 'circle', color: 'green' },
                ]}
              />
              
              <Tooltip
                content={({ payload }) => (
                  <div style={{
                    backgroundColor: '#1a1a1a',
                    padding: '8px',
                    border: '1px solid #333',
                    borderRadius: '4px',
                    fontSize: 'clamp(12px, 3vw, 14px)'
                  }}>
                    {payload?.[0]?.payload && (
                      <>
                        <p><strong>{payload[0].payload.ticker}</strong></p>
                        <p>MD: {payload[0].payload["MD"]}</p>
                        <p>YTM: {payload[0].payload["YTM"]}%</p>
                      </>
                    )}
                  </div>
                )}
              />
  
              {/* Trend Lines */}
              <Line
                data={cerTrend}
                dataKey="YTM"
                stroke="green"
                strokeWidth={2}
                dot={false}
                name="Bonares"
              />
              
            
  
              {/* Scatter Points */}
              <Scatter
                name="CER"
                data={data["cer"]}
                fill="orange"
                shape={({ cx, cy, payload }) => (
                  <g>
                    <circle cx={cx} cy={cy} r={6} fill="green" stroke="#fff" strokeWidth={1} />
                    <text
                      x={cx}
                      y={cy + 15}
                      textAnchor="middle"
                      fill="#fff"
                      fontSize={isMobile ? 10 : 12}
                    >
                      {payload.ticker}
                    </text>
                  </g>
                )}
              />
              
              
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </>
    );
  };
  


const inlfacionBEChart = (data, isMobile) => {
    // Polynomial regression calculation for break-even inflation
    const calculateBEInflationTrend = (dataPoints, order = 2) => {
      if (!dataPoints || dataPoints.length < 2) return [];
      const points = dataPoints.map(p => [p.MD, p.be_inflation]);
      const result = regression.polynomial(points, { order, precision: 6 });
      const minX = Math.min(...dataPoints.map(p => p.MD));
      const maxX = Math.max(...dataPoints.map(p => p.MD));
      
      return Array.from({ length: 100 }, (_, i) => {
        const x = minX + (maxX - minX) * (i / 100);
        const y = result.predict(x)[1];
        return { MD: x, be_inflation: y };
      });
    };
  
    // Calculate trend for break-even inflation
    const beInflationTrend = calculateBEInflationTrend(data["be_inflation"] || []);
  
  
    return (
      <>
        <h2 style={{ textAlign: 'center', margin: '10px 0', fontSize: 'clamp(1.2rem, 4vw, 1.5rem)' }}>
          Inflación Breakeven 
        </h2>
        <div style={{ position: 'relative', width: '100%' }}>
          <ResponsiveContainer aspect={isMobile ? 1 : 2.5} width="100%" height="100%">
            <ComposedChart margin={{ top: 10, right: 10, left: 10, bottom: 60 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#444" />
              
              <XAxis
                type="number"
                dataKey="MD"
                name="MD"
                tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
                label={{
                  value: 'MD',
                  position: 'bottom',
                  offset: 10,
                  fill: '#fff',
                  style: { fontSize: 'clamp(10px, 3vw, 14px)' }
                }}
              />
              
              <YAxis
                type="number"
                dataKey="be_inflation"
                name="Inflación"
                domain={[0, 40]}
                tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
                label={{
                  value: 'Tasa Anual (%) ',
                  angle: -90,
                  position: 'left',
                  fill: '#fff',
                  style: { fontSize: 'clamp(10px, 3vw, 14px)' }
                }}
              />
              
              <Legend
                verticalAlign="top"
                wrapperStyle={{ paddingBottom: 20 }}
                payload={[
                  { value: 'Inflación breakeven', type: 'line', color: 'green' },
                  { value: 'Tasa real bonos CER', type: 'line', color: '#4ecdc4' },
                  { value: 'YTM e.a. letras tasa fija', type: 'line', color: '#ff6b6b' },
  
  
                ]}
              />
              
              <Tooltip
                content={({ payload }) => (
                  <div style={{
                    backgroundColor: '#1a1a1a',
                    padding: '8px',
                    border: '1px solid #333',
                    borderRadius: '4px',
                    fontSize: 'clamp(12px, 3vw, 14px)'
                  }}>
                    {payload?.[0]?.payload && (
                      <>
                        <p><strong>{payload[0].payload.ticker_cer}/{payload[0].payload.ticker_lecaps}</strong></p>
                        <p>MD: {payload[0].payload["MD"]}</p>
                        <p>Bono CER: {payload[0].payload["ticker_cer"]}  (Tasa real anual {payload[0].payload["YTM"]}%) </p>
                        <p>Letra: {payload[0].payload["ticker_lecaps"]}  (YTM e.a. {payload[0].payload["tea"]}%) </p>
                        </>
  
                    )}
                  </div>
                )}
              />
  
              {/* Trend Lines */}
              
              
      
              <Line
                data={beInflationTrend}
                dataKey="be_inflation"
                stroke="green"
                strokeWidth={2}
                dot={false}
                name="Inflación Breakeven"
              />
            
  
              {/* Scatter Points */}
              <Scatter
                name="CER"
                data={data["be_inflation"]?.filter(item => item.be_inflation != null)}
                fill="orange"
                shape={({ cx, cy, payload }) => (
                  <g>
                    <circle cx={cx} cy={cy} r={6} fill="green" stroke="#fff" strokeWidth={1} />
                    <text
                      x={cx}
                      y={cy + 15}
                      textAnchor="middle"
                      fill="#fff"
                      fontSize={isMobile ? 10 : 12}
                    >
                      {payload.ticker_cer}/{payload.ticker_lecaps}
                    </text>
                  </g>
                )}
              />
  
              {/* Vertical Lines connecting TEM to YTM */}
              
              {data["be_inflation"]?.filter(item => item.be_inflation != null).map((item, index) => (
                <Line
                  key={`connector-${index}`}
                  data={[
                    { MD: item.MD, value: item.tem },
                    { MD: item.MD, value: item.YTM }
                  ]}
                  dataKey="value"
                  stroke="#666"
                  strokeDasharray="3 3"
                  strokeWidth={1}
                  dot={false}
                />
              ))}
  
              {/* TEM Line */}
              <Line
                data={data["be_inflation"]?.filter(item => item.be_inflation != null)}
                dataKey="tea"
                stroke="#ff6b6b"
                strokeWidth={2}
                strokeDasharray="5 5"
                dot={{
                  fill: "#ff6b6b",
                  r: 4,
                  strokeWidth: 1,
                  stroke: "#fff"
                }}
                name="YTM t.e. Lecaps"
              />
  
              {/* YTM Line */}
              <Line
                data={data["be_inflation"]?.filter(item => item.be_inflation != null)}
                dataKey="YTM"
                stroke="#4ecdc4"
                strokeWidth={2}
                strokeDasharray="5 5"
                dot={{
                  fill: "#4ecdc4",
                  r: 4,
                  strokeWidth: 1,
                  stroke: "#fff"
                }}
                name="Tasa real anual"
              />
  
              <Legend
                verticalAlign="top"
                align="right"
                wrapperStyle={{
                  paddingBottom: "10px",
                  fontSize: isMobile ? "10px" : "12px"
                }}
              />
              
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </>
    );
  };
  


function ReportBonosCER({ data, dolar, title, isMobile, aiReports }) {
  const [isOpen, setIsOpen] = useState(false);
  const [isAIOpen, setIsAIOpen] = useState(false);
  const [headerColor, setHeaderColor] = useState('#ffffff');

  const toggleReport = () => {
    setIsOpen(prev => !prev);
  };

  const toggleAI = () => {
    setIsAIOpen(prev => !prev);
  };

  return (
    <div
      style={{
        marginBottom: '40px',
        backgroundColor: 'rgba(0, 0, 0, 0.3)',
        color: 'white',
        padding: '20px',
        borderRadius: '5px',
        border: '1px solid rgba(171, 168, 168, 0.3)',
        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
        transition: 'all 0.3s ease',
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h1
          style={{
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            fontSize: '24px',
            fontWeight: 'bold',
            color: headerColor,
            transition: 'color 0.3s ease',
            margin: 0,
          }}
          onClick={toggleReport}
          onMouseEnter={() => setHeaderColor('#e0e0e0')}
          onMouseLeave={() => setHeaderColor('#ffffff')}
        >
           <ExpandMoreIcon
            style={{
              marginRight: '5px',
              transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
              transition: 'transform 0.3s ease',
            }}
          />
                    {title}     </h1>

        <button
          onClick={toggleAI}
          aria-pressed={isAIOpen}
          style={{
            backgroundColor: isAIOpen ? '#333333' : 'black',
            border: isAIOpen ? '1px solid #00FFFF' : '1px solid white',
            borderRadius: '4px',
            padding: '8px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            color: isAIOpen ? '#00FFFF' : 'white',
            transition: 'all 0.3s ease',
          }}
        >
          <SmartToyIcon style={{ marginRight: '4px', transform: isAIOpen ? 'rotate(20deg)' : 'none', transition: 'transform 0.3s ease' }} />
          AI
        </button>
      </div>

      {/* AI Generated Text with Warning */}
      {isAIOpen && (
        <div
          style={{
            backgroundColor: 'black',
            color: 'white',
            padding: '15px',
            borderRadius: '5px',
            marginTop: '10px',
            border: '1px solid rgba(171, 168, 168, 0.3)',
          }}
        >
          
          <ReactMarkdown children={aiReports["cer"]} />

          <p style={{ color: '#aaaaaa', fontSize: '12px', marginBottom: '8px' }}>
            ⚠️ Este sumario es autogenerado, a partir de los datos diarios, por un LLM y puede contener errores o incompletitud.
          </p>
        </div>
      )}

      <div
        className="report-content"
        style={{
          overflowY: isOpen ? 'auto' : 'hidden',
          transition: 'max-height 0.5s ease, opacity 0.5s ease',
          maxHeight: isOpen ? '600px' : '0',
          opacity: isOpen ? 1 : 0,
          paddingRight: '10px',
          marginTop: isOpen ? '20px' : '0',
        }}
      >
        {/* Data Tables */}
        <div style={{ marginBottom: '40px' }}>
          <h3 style={{ color: 'white', marginBottom: '10px' }}>Bonos CER</h3>
          <BonosHDTable pesos isMobile={isMobile} data={data["cer"] || []} cfs={data["cer_cf"] || []} />
        </div>

        {/* Chart */}
        <div
          style={{
            backgroundColor: 'black',
            padding: '10px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
          }}
        >
          {bonosCERChart(data, isMobile)}
        </div>
        {/* Break-even Chart */  }
        <div
          style={{
            backgroundColor: 'black',
            padding: '10px',
            borderRadius: '8px',
            marginTop: '10px',
            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
          }}
        >
          {inlfacionBEChart(data, isMobile)}
        </div>
        

       

      </div>
    </div>
  );
}


export default ReportBonosCER;