import React, { useState, useEffect } from 'react';
import './Bio.css';
import SmartToyIcon from '@mui/icons-material/SmartToy';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ReactMarkdown from 'react-markdown';

import "@fontsource/montserrat";
import {
  ComposedChart,
  ResponsiveContainer,
  ScatterChart,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip,
  Scatter,
  Line,
  Text,
  ReferenceLine,
} from 'recharts';


const ResponsiveText = ({ children, ...props }) => (
    <Text {...props} style={{ fontSize: 'clamp(8px, 2.5vw, 12px)', ...props.style }}>
      {children}
    </Text>
  );


const lecapsTable = (data, isMobile) => (
    <div style={{   overflowX: 'auto',
      WebkitOverflowScrolling: 'touch',
      display: isMobile ? 'flex' : undefined,
      zoom: isMobile ? 0.2 : 1,                 // scales layout box
      justifyContent: isMobile ? 'center' : undefined, }}>
      <table style={{ 
          width: '100%',
          borderCollapse: 'separate',
          borderSpacing: '0 8px',
          fontSize: 'clamp(12px, 3vw, 14px)',
          transformOrigin: 'top center',
          transition: 'transform 0.2s ease-out',
      }}>
        <thead>
          <tr>
            {["Ticker", "Precio","Precio % Día","Precio % ytd " ,"Días al Vencimiento", "Total", "TEM"].map((header, i) => (
              <th key={i} style={{ 
                padding: '8px 12px',
                textAlign: 'left',
                fontWeight: 'bold',
                whiteSpace: 'nowrap'
              }}>{header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((item, index) => (
            <tr
              key={index}
              style={{
                backgroundColor: index % 2 === 0 ? '#2a2a2a' : '#333',
              }}
            >
              <td style={{ padding: '8px 12px', textAlign: 'left' }}>{item.ticker}</td>
              <td style={{ padding: '8px 12px', textAlign: 'left' }}>{item.precio}</td>
              <td style={{ 
                padding: '8px 12px', 
                textAlign: 'left', 
                color: item["price day %"] >= 0 ? '#16c784' : '#ea3943' 
              }}>
                {item["price day %"] >= 0 ? '▲' : '▼'} {item["price day %"]}%
              </td>
  
              <td style={{ 
                padding: '8px 12px', 
                textAlign: 'left', 
                color: item["price ytd %"] >= 0 ? '#16c784' : '#ea3943' 
              }}>
                {item["price ytd %"] >= 0 ? '▲' : '▼'} {item["price ytd %"]}%
              </td>
  
  
              <td style={{ padding: '8px 12px', textAlign: 'left' }}>{item.dias}</td>
              <td style={{ padding: '8px 12px', textAlign: 'left' }}>${item.total.toLocaleString()}</td>
              <td style={{ padding: '8px 12px', textAlign: 'left' }}>{item.tem}%</td>
  
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );



const lecapsChart = (data, trend = [], isMobile) => (
    <>
      <h2 style={{ textAlign: 'center', margin: '10px 0', fontSize: 'clamp(1.2rem, 4vw, 1.5rem)' }}>
        Curva Tasa Fija
      </h2>
      <div style={{ position: 'relative', width: '100%' }}>
        <ResponsiveContainer  aspect={isMobile ? 1.5 : 2.5} width="100%" height="100%">
          <ScatterChart margin={{ top: 10, right: 10, left: 10, bottom: 60 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#444" />
            <XAxis
              type="number"
              dataKey="dias"
              name="Días"
              tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
              label={{
                value: 'Días al Vencimiento',
                position: 'bottom',
                offset: 10,
                fill: '#fff',
                style: { fontSize: 'clamp(10px, 3vw, 14px)' }
              }}
            />
            <YAxis
              type="number"
              dataKey="tem"
              name="TEM"
              domain={[2, 3]}  // Set axis range from 0 to 8
  
              tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
              label={{
                value: 'TEM (%)',
                angle: -90,
                position: 'left',
                fill: '#fff',
                style: { fontSize: 'clamp(10px, 3vw, 14px)' }
              }}
            />
            <Tooltip
              content={({ payload }) => (
                <div style={{
                  backgroundColor: '#1a1a1a',
                  padding: '8px',
                  border: '1px solid #333',
                  borderRadius: '4px',
                  fontSize: 'clamp(12px, 3vw, 14px)'
                }}>
                  {payload?.[0]?.payload && (
                    <>
                      <p><strong>{payload[0].payload.ticker}</strong></p>
                      <p>Días: {payload[0].payload.dias}</p>
                      <p>TEM: {payload[0].payload.tem.toFixed(2)}%</p>
                    </>
                  )}
                </div>
              )}
            />
            <Scatter
              name="LECAPS"
              data={data.filter(item => item.tem > 0)}
              fill="#00ff88"
              shape={({ cx, cy, payload }) => (
                <g>
                  <circle cx={cx} cy={cy} r={4} fill="#00ff88" stroke="#000" />
                  <ResponsiveText
                    x={cx}
                    y={cy + 15}
                    textAnchor="middle"
                    fill="#fff"
                  >
                    {payload.ticker}
                  </ResponsiveText>
                </g>
              )}
            />
            <Line
                data={data}
                dataKey="tem"
                stroke="green"
                strokeWidth={2}
                dot={false}
                type="basis"
                strokeDasharray={"5 5"}
                name="Globales Curve"
              />
            <Line
              data={trend}
              dataKey="tem"
              stroke="#ff7300"
              strokeWidth={2}
              strokeDasharray="5 5"
              dot={false}
              activeDot={false}
              isAnimationActive={false}
            />
             {/* Trend line fixes */}
             <Line
              type="linear"
              dataKey="tem"
              data={data.filter(item=> item['tem'] > 0)}
              stroke="#ff7300"
              strokeWidth={2} // Added explicit width
              strokeDasharray="5 5"
              dot={false}
              activeDot={false}
              isAnimationActive={false}
              name="Tendencia"
            />
            {/* Optional: Add regression equation annotation */}
            {trend.length === 2 && (
              <ReferenceLine
                segment={[
                  { x: trend[0].dias, y: trend[0].tem },
                  { x: trend[1].dias, y: trend[1].tem },
                ]}
                stroke="#ff7300"
                strokeDasharray="5 5"
              />
            )}
          </ScatterChart>
          
        </ResponsiveContainer>
      </div>
    </>
  );




const lecapsBreakEvenChart = (data, dolar, isMobile) => (
    <>
      <h2 style={{ textAlign: 'center', margin: '10px 0', fontSize: 'clamp(1.2rem, 4vw, 1.5rem)' }}>
        Dólar Breakeven (Oficial hoy {dolar?.venta} $)
      </h2>
      <div style={{ position: 'relative', width: '100%' }}>
        <ResponsiveContainer aspect={isMobile ? 1.5 : 2.5}  width="100%" height="100%">
          <ComposedChart
            data={data}
            margin={{ top: 10, right: 10, left: 10, bottom: 60 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#444" />
            <XAxis
              dataKey="dias"
              name="Días"
              tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
              label={{
                value: 'Días al Vencimiento',
                position: 'bottom',
                offset: 30,
                fill: '#fff',
                style: { fontSize: 'clamp(10px, 3vw, 14px)' }
              }}
            />
            <YAxis
              dataKey="breakeven"
              name="USD"
              tick={{ fill: '#fff', fontSize: 'clamp(8px, 2.5vw, 12px)' }}
              label={{
                value: '$ (ARSp/USD)',
                angle: -90,
                position: 'left',
                fill: '#fff',
                style: { fontSize: 'clamp(10px, 3vw, 14px)' }
              }}
            />
            
            <Tooltip
              content={({ payload }) => (
                <div style={{
                  backgroundColor: '#1a1a1a',
                  padding: '8px',
                  border: '1px solid #333',
                  borderRadius: '4px',
                  fontSize: 'clamp(12px, 3vw, 14px)'
                }}>
                  {payload?.[0]?.payload && (
                    <>
                      <p><strong>{payload[0].payload.ticker}</strong></p>
                      <p>Días: {payload[0].payload.dias}</p>
                      <p>Breakeven: {payload[0].payload.breakeven.toFixed(2)}</p>
                      {payload[0].payload.sup && (
                        <p>Sup: {payload[0].payload.sup.toFixed(2)}</p>
                      )}
                    </>
                  )}
                </div>
              )}
            />
            <Scatter
              data={data}
              fill="#00ff88"
              shape={({ cx, cy, payload }) => (
                <g>
                  <circle cx={cx} cy={cy} r={4} fill="#00ff88" stroke="#000" />
                  <ResponsiveText
                    x={cx}
                    y={cy + 15}
                    textAnchor="middle"
                    fill="#fff"
                  >
                    {payload.ticker}
                  </ResponsiveText>
                </g>
              )}
            />
            <Line
              type="linear"
              dataKey="sup"
              stroke="#ff7300"
              strokeWidth={2}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </>
  );




function ReportLecaps({ data, dolar, trend, title, table = lecapsTable, charts = lecapsChart, isMobile, aiReports }) {
    const [isOpen, setIsOpen] = useState(false);
    const [isAIOpen, setIsAIOpen] = useState(false);
    const [headerColor, setHeaderColor] = useState('#ffffff');
  
    const toggleReport = () => {
      setIsOpen(prev => !prev);
    };
  
    const toggleAI = () => {
      setIsAIOpen(prev => !prev);
    };
  
    return (
      <div
        style={{
          marginBottom: '40px',
          backgroundColor: 'rgba(0, 0, 0, 0.3)',
          color: 'white',
          padding: '20px',
          borderRadius: '5px',
          border: '1px solid rgba(171, 168, 168, 0.3)',
          boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
          transition: 'all 0.3s ease',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h1
            style={{
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              fontSize: '24px',
              fontWeight: 'bold',
              color: headerColor,
              transition: 'color 0.3s ease',
              margin: 0,
            }}
            onClick={toggleReport}
            onMouseEnter={() => setHeaderColor('#e0e0e0')}
            onMouseLeave={() => setHeaderColor('#ffffff')}
          >
            <ExpandMoreIcon
              style={{
                marginRight: '5px',
                transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                transition: 'transform 0.3s ease',
              }}
            />
                      {title}
  
          </h1>
  
          <button
            onClick={toggleAI}
            aria-pressed={isAIOpen}
            style={{
              backgroundColor: isAIOpen ? '#333333' : 'black',
              border: isAIOpen ? '1px solid #00FFFF' : '1px solid white',
              borderRadius: '4px',
              padding: '8px',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              color: isAIOpen ? '#00FFFF' : 'white',
              transition: 'all 0.3s ease',
            }}
          >
            <SmartToyIcon style={{ marginRight: '4px', transform: isAIOpen ? 'rotate(20deg)' : 'none', transition: 'transform 0.3s ease' }} />
            AI
          </button>
        </div>
  
        {/* AI Generated Text with Warning */}
        {isAIOpen && (
          <div
            style={{
              backgroundColor: 'black',
              color: 'white',
              padding: '15px',
              borderRadius: '5px',
              marginTop: '10px',
              border: '1px solid rgba(171, 168, 168, 0.3)',
            }}
          >
           
  
            {/* Mockup AI text */}
        
            <ReactMarkdown children={aiReports["lecaps"]}   />
             {/* LLM Warning */}
            <p style={{ color: '#aaaaaa', fontSize: '12px', marginBottom: '8px' }}>
              ⚠️ Este sumario es autogenerado, a partir de los datos diarios, por un LLM y puede contener errores o incompletitud.
            </p>
          </div>
        )}
  
        <div
          className="report-content"
          style={{
            overflowY: isOpen ? 'auto' : 'hidden',
            transition: 'max-height 0.5s ease, opacity 0.5s ease',
            maxHeight: isOpen ? '600px' : '0',
            opacity: isOpen ? 1 : 0,
            paddingRight: '10px',
            marginTop: isOpen ? '20px' : '0',
          }}
        >
          {/* Data Table */}
          <div style={{ marginBottom: '10px' }}>
            {table(data, isMobile)}
          </div>
  
          {/* Chart */}
          <div
            style={{
              backgroundColor: 'black',
              padding: '10px',
              borderRadius: '8px',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
            }}
          >
            {charts(data, trend, isMobile)}
          </div>
  
          {/* Break-even Chart */}
          <div
            style={{
              backgroundColor: 'black',
              padding: '10px',
              borderRadius: '8px',
              marginTop: '10px',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
            }}
          >
            {lecapsBreakEvenChart(data, dolar, isMobile)}
          </div>
        </div>
      </div>
    );
  }

  export default ReportLecaps;